// A resilience4j bulkhead per downstream dependency
BulkheadConfig reportingConfig = BulkheadConfig.custom()
    .maxConcurrentCalls(10)
    .maxWaitDuration(Duration.ofMillis(500))
    .build();

BulkheadConfig paymentsConfig = BulkheadConfig.custom()
    .maxConcurrentCalls(50)
    .maxWaitDuration(Duration.ofMillis(200))
    .build();

Bulkhead reportingBulkhead = Bulkhead.of("reporting", reportingConfig);
Bulkhead paymentsBulkhead = Bulkhead.of("payments", paymentsConfig);

Supplier<Report> decorated = Bulkhead
    .decorateSupplier(reportingBulkhead, () -> reportingClient.fetch());

